import { EntityFromRelationships } from './entity-from-relationships';
import { EntityIcon } from './entity-icon';
import { EntityProperties } from './entity-properties';
import { EntityToRelationships } from './entity-to-relationships';
import { ManagementZone } from './management-zone';
import { METag } from './me-tag';
/**
 * The properties of a monitored entity.
 */
export interface Entity {
    /**
     * The name of the entity, displayed in the UI.
     */
    displayName?: string;
    /**
     * The ID of the entity.
     */
    entityId?: string;
    /**
     * The timestamp at which the entity was first seen, in UTC milliseconds.
     */
    firstSeenTms?: number;
    fromRelationships?: EntityFromRelationships;
    icon?: EntityIcon;
    /**
     * The timestamp at which the entity was last seen, in UTC milliseconds.
     */
    lastSeenTms?: number;
    /**
     * A set of management zones to which the entity belongs.
     */
    managementZones?: ManagementZone[];
    properties?: EntityProperties;
    /**
     * A set of tags assigned to the entity.
     */
    tags?: METag[];
    toRelationships?: EntityToRelationships;
    /**
     * The type of the entity.
     */
    type?: string;
}
